import java.io.*;
import java.nio.charset.StandardCharsets;
import java.nio.file.*;
import java.util.*;

import org.apache.commons.csv.*;

public class Main {
    public static void main(String[] args) throws IOException {
        Path file = Paths.get("excel.csv");
        Files.deleteIfExists(file);
        try (Writer w = Files.newBufferedWriter(file, StandardCharsets.UTF_8)) {
            w.write("\uFEFF");
            w.write("id,judul\r\n1,Belajar\r\n");
        }
        CSVFormat format = CSVFormat.DEFAULT.builder().setHeader().setSkipHeaderRecord(true).build();
        try (CSVParser p = new CSVParser(Files.newBufferedReader(file, StandardCharsets.UTF_8), format)) {
            System.out.println("Kolom: " + p.getHeaderNames());
            System.out.println("Ada id? " + p.getHeaderNames().contains("id"));
        }
    }
}

