import java.io.*;
import java.nio.charset.StandardCharsets;
import java.nio.file.*;
import java.util.*;

import org.apache.commons.csv.*;

public class Main {
    public static void main(String[] args) throws IOException {
        Path file = Paths.get("laporan-stok.csv");
        Files.deleteIfExists(file);
        CSVFormat masuk = CSVFormat.DEFAULT.builder().setHeader().setSkipHeaderRecord(true).build();
        CSVFormat keluar = CSVFormat.DEFAULT.builder().setHeader("nama", "stok").build();
        try (CSVParser parser = masuk.parse(new InputStreamReader(System.in));
             Writer w = Files.newBufferedWriter(file, StandardCharsets.UTF_8);
             CSVPrinter printer = new CSVPrinter(w, keluar)) {
            for (CSVRecord r : parser) {
                if (Integer.parseInt(r.get("stok")) < 5) {
                    printer.printRecord(r.get("nama"), r.get("stok"));
                }
            }
        }
        for (String baris : Files.readAllLines(file, StandardCharsets.UTF_8)) {
            System.out.println(baris);
        }
    }
}
